def minWindow(s1, s2):
    def is_subseq(sub, pat):
        it = iter(sub)
        return all(c in it for c in pat)
    n = len(s1)
    min_str = ""
    min_len = float('inf')
    for i in range(n):
        for j in range(i + 1, n + 1):
            sub = s1[i:j]
            if is_subseq(sub, s2):
                if len(sub) < min_len:
                    min_len = len(sub)
                    min_str = sub
                break
    return min_str

