def minWindow(s1, s2):
    n, m = len(s1), len(s2)
    i, j = 0, 0
    min_len = float('inf')
    res = ""
    while i < n:
        if s1[i] == s2[j]:
            j += 1
            if j == m:
                end = i
                j -= 1
                while j >= 0:
                    if s1[i] == s2[j]:
                        j -= 1
                    i -= 1
                i += 1
                start = i
                if end - start + 1 < min_len:
                    min_len = end - start + 1
                    res = s1[start:end + 1]
                j = 0
        i += 1
    return res

